import xml.etree.ElementTree as ET
import math

tree = ET.parse('coverage.xml')
root = tree.getroot()

# Find MyApp.OrderService class
for pkg in root.findall('.//package'):
    for cls in pkg.findall('.//class'):
        name = cls.get('name')
        if name == 'MyApp.OrderService':
            for method in cls.findall('methods/method'):
                mname = method.get('name')
                if mname == '.ctor':
                    continue

                # Get branch coverage
                branches_valid = 0
                branches_covered = 0
                for line in method.findall('lines/line'):
                    if line.get('branch') == 'True':
                        conds = line.get('condition-coverage', '')
                        if '(' in conds:
                            parts = conds.split('(')[1].rstrip(')').split('/')
                            branches_covered += int(parts[0])
                            branches_valid += int(parts[1])

                if branches_valid > 0:
                    coverage = branches_covered / branches_valid
                else:
                    lines = method.findall('lines/line')
                    hits = [int(l.get('hits','0')) for l in lines]
                    coverage = 1.0 if any(h > 0 for h in hits) else 0.0

                # Cyclomatic complexity from the code comments
                if mname == 'ProcessOrder':
                    cc = 7
                elif mname == 'CancelOrder':
                    cc = 2
                else:
                    cc = 1

                # CRAP formula: cc^2 * (1-coverage)^3 + cc
                crap = cc**2 * (1 - coverage)**3 + cc

                print(f'{mname}:')
                print(f'  Cyclomatic Complexity: {cc}')
                print(f'  Branch Coverage:       {coverage:.1%} ({branches_covered}/{branches_valid})')
                print(f'  CRAP Score:            {crap:.2f}')
                print()
